import { Token } from "@taostats-wallet/chaindata-provider"
import { classNames } from "@taostats-wallet/util"
import { FC, useMemo } from "react"
import { useTranslation } from "react-i18next"

export const TokenTypePill: FC<{ type: Token["type"]; className?: string }> = ({
  type,
  className,
}) => {
  const { t } = useTranslation()

  const label = useMemo(() => {
    switch (type) {
      case "substrate-native":
      case "evm-native":
        return t("NATIVE")
      case "evm-uniswapv2":
        return "UNI V2"

      case "substrate-assets":
        return "HUB"
      case "substrate-dtao":
        return "DTAO"
      case "substrate-foreignassets":
        return "FOREIGN"
      case "substrate-psp22":
        return "PSP22"
      case "substrate-tokens":
        return "ORML"
      case "substrate-hydration":
        return "HYDRATION"
    }
  }, [t, type])

  if (!label) return null

  return (
    <span
      data-testid="component-token-pill"
      className={classNames(
        "text-body-disabled rounded-xs border px-2 py-1 text-[1rem]",
        className,
      )}
    >
      {label}
    </span>
  )
}
